function toggleCustomer(id){const box=$(`[data-detail="${id}"]`),c=state.store.customers.find(x=>x.id===id);box.classList.toggle('hidden');if(box.classList.contains('hidden'))return;const debts=filteredCustomerDebts(id);box.innerHTML=`<div class="panel-head"><button class="ghost small" data-add-debt="${id}">+ Ghi nợ</button><button class="primary small" data-pay-debt="${id}">Trả nợ</button></div>${debts.map(d=>`<div class="debt-item"><div class="debt-line"><div><strong>${moneyPlain(d.amount)}</strong><small>${fmtDate(d.createdAt)} · ${esc(d.note||'Không ghi chú')}${d.saleId?' · từ đơn bán hàng':''}</small></div><div class="row-actions"><button class="ghost small" data-edit-debt="${d.id}">Sửa</button>${d.saleId?'':`<button class="ghost danger small" data-del-debt="${d.id}">Xóa</button>`}</div></div><div class="payment-history">${(d.payments||[]).length?`<small class="subhead">Lịch sử trả</small>`:''}${(d.payments||[]).slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).map(pay=>`<div class="payment-row"><div><span>Đã trả <b>${money(pay.amount)}</b></span><small>${fmtDate(pay.createdAt)} · ${esc(pay.note||'Không ghi chú')}</small></div><div class="row-actions"><button class="ghost small" data-edit-pay="${pay.id}" data-debt-id="${d.id}">Sửa</button><button class="ghost danger small" data-del-pay="${pay.id}" data-debt-id="${d.id}">Xóa</button></div></div>`).join('')}</div></div>`).join('')||'<div class="empty">Không có khoản nợ phù hợp bộ lọc.</div>'}`;box.querySelector('[data-add-debt]').onclick=()=>showAddDebt(id);box.querySelector('[data-pay-debt]').onclick=()=>showPayDebt(id);box.querySelectorAll('[data-edit-debt]').forEach(b=>b.onclick=()=>showEditDebt(b.dataset.editDebt));box.querySelectorAll('[data-del-debt]').forEach(b=>b.onclick=async()=>{if(confirm('Xóa khoản nợ này?'))try{await mutate('debt.delete',{id:b.dataset.delDebt});toast('Đã xóa')}catch(e){toast(e.message,true)}});box.querySelectorAll('[data-edit-pay]').forEach(b=>b.onclick=()=>showEditDebtPayment(b.dataset.debtId,b.dataset.editPay));box.querySelectorAll('[data-del-pay]').forEach(b=>b.onclick=async()=>{if(confirm('Xóa lần trả nợ này? Số dư công nợ sẽ được cộng lại.'))try{await mutate('debt.payment.delete',{debtId:b.dataset.debtId,paymentId:b.dataset.delPay});toast('Đã xóa lần trả')}catch(e){toast(e.message,true)}})}
function localDateInput(v){const d=new Date(v);if(isNaN(d))return'';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function showAddDebt(id){modal('<h3>Ghi nợ mới</h3><div class="form-grid"><label>Số tiền<input id="mAmount" inputmode="text"></label><label>Ngày<input id="mDate" type="datetime-local"></label><label class="wide">Món nợ / ghi chú<input id="mNote"></label></div><button id="mSave" class="primary full">Lưu</button>');$('#mSave').onclick=async()=>{try{await mutate('debt.add',{customerId:id,amount:moneyInput($('#mAmount').value),note:$('#mNote').value,createdAt:$('#mDate').value?new Date($('#mDate').value).toISOString():undefined});closeModal();toast('Đã ghi nợ')}catch(e){toast(e.message,true)}}}
function showEditDebt(id){const d=(state.store.debts||[]).find(x=>x.id===id);if(!d)return;modal(`<h3>Chỉnh khoản ghi nợ</h3><div class="form-grid"><label>Số tiền<input id="mAmount" inputmode="text" value="${d.amount}" ${d.saleId?'disabled':''}></label><label>Ngày<input id="mDate" type="datetime-local" value="${localDateInput(d.createdAt)}"></label><label class="wide">Món nợ / ghi chú<input id="mNote" value="${esc(d.note||'')}"></label></div>${d.saleId?'<p class="hint">Khoản này sinh từ đơn bán hàng nên số tiền được khóa. Bạn vẫn có thể sửa ngày và ghi chú.</p>':''}<button id="mSave" class="primary full">Lưu thay đổi</button>`);$('#mSave').onclick=async()=>{try{await mutate('debt.update',{id:d.id,amount:d.saleId?d.amount:moneyInput($('#mAmount').value),note:$('#mNote').value,createdAt:$('#mDate').value?new Date($('#mDate').value).toISOString():d.createdAt});closeModal();toast('Đã cập nhật khoản nợ')}catch(e){toast(e.message,true)}}}
function showEditDebtPayment(debtId,paymentId){const d=(state.store.debts||[]).find(x=>x.id===debtId),pay=(d?.payments||[]).find(x=>x.id===paymentId);if(!pay)return;modal(`<h3>Chỉnh lần trả nợ</h3><div class="form-grid"><label>Số tiền đã trả<input id="mAmount" inputmode="text" value="${pay.amount}"></label><label>Ngày trả<input id="mDate" type="datetime-local" value="${localDateInput(pay.createdAt)}"></label><label class="wide">Ghi chú<input id="mNote" value="${esc(pay.note||'')}"></label></div><button id="mSave" class="primary full">Lưu thay đổi</button>`);$('#mSave').onclick=async()=>{try{await mutate('debt.payment.update',{debtId,paymentId,amount:moneyInput($('#mAmount').value),note:$('#mNote').value,createdAt:$('#mDate').value?new Date($('#mDate').value).toISOString():pay.createdAt});closeModal();toast('Đã cập nhật lần trả')}catch(e){toast(e.message,true)}}}
function showPayDebt(id){const c=state.store.customers.find(x=>x.id===id),ds=(state.store.debts||[]).filter(d=>d.customerId===id&&d.balance>0),total=ds.reduce((a,d)=>a+num(d.balance),0);modal(`<h3>${esc(c.name)} trả nợ</h3><p class="hint">Tổng nợ hiện tại <b>${money(total)}</b></p><div>${ds.map(d=>`<label class="debt-line"><input type="checkbox" data-pick="${d.id}"><span>${fmtDate(d.createdAt)} · ${esc(d.note||'')}</span><strong>${money(d.balance)}</strong></label>`).join('')}</div><div class="form-grid"><label>Số tiền<input id="mAmount" inputmode="text" value="${moneyPlain(total)}" autocomplete="off"><small>Nhập 10 hoặc 10k = 10.000</small></label><label>Nhận bằng<select id="mPayment"><option value="cash">Tiền mặt</option><option value="transfer">Chuyển khoản</option></select></label><label class="wide">Ghi chú<input id="mNote"></label></div><button id="mSave" class="primary full">Xác nhận trả nợ</button>`);$$('[data-pick]').forEach(ch=>ch.onchange=()=>{const picked=$$('[data-pick]:checked').map(x=>x.dataset.pick);$('#mAmount').value=moneyPlain(picked.length?ds.filter(d=>picked.includes(d.id)).reduce((a,d)=>a+num(d.balance),0):total)});$('#mSave').onclick=async()=>{const amount=moneyInput($('#mAmount').value),picked=$$('[data-pick]:checked').map(x=>x.dataset.pick);try{if(picked.length){let left=amount,alloc=[];for(const did of picked){const d=ds.find(x=>x.id===did),x=Math.min(left,num(d.balance));if(x>0)alloc.push({debtId:did,amount:x});left-=x;if(left<=0)break}await mutate('debt.pay.selected',{customerId:id,allocations:alloc,note:$('#mNote').value,paymentMethod:$('#mPayment').value})}else await mutate('debt.pay',{customerId:id,amount,note:$('#mNote').value,paymentMethod:$('#mPayment').value});closeModal();toast('Đã ghi nhận trả nợ')}catch(e){toast(e.message,true)}}}
