function renderSuppliers(){const ss=state.store.suppliers||[];$('#supplierDebtTotal').textContent=money((state.store.supplierDebts||[]).reduce((a,d)=>a+num(d.balance),0));$('#supplierList').innerHTML=ss.map(s=>`<div class="list-row"><div><strong>${esc(s.name)}</strong><small>Còn nợ ${money(supplierDebt(s.id))}</small></div>${supplierDebt(s.id)?`<button class="primary small" data-pay-sp="${s.id}">Trả nợ</button>`:''}</div>`).join('')||'<div class="empty">Chưa có nhà cung cấp.</div>';$$('[data-pay-sp]').forEach(b=>b.onclick=()=>showPaySupplier(b.dataset.paySp))}
