function dateKeyLocal(d){const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)}
function latestAudit(){return [...(state.store?.audits||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]||null}
function auditRange(){const end=new Date(),prev=latestAudit();let start;if(prev)start=new Date(prev.createdAt);else{start=new Date(end);start.setDate(start.getDate()-6);start.setHours(0,0,0,0)}return {from:start,to:end,fromKey:dateKeyLocal(start),toKey:dateKeyLocal(end),fromAt:start.toISOString(),toAt:end.toISOString(),label:prev?`${start.toLocaleDateString('vi-VN')} → ${end.toLocaleDateString('vi-VN')}`:`Kỳ hiện tại · đến ${end.toLocaleDateString('vi-VN')}`,hasPrevious:!!prev,prev}}
function auditSimpleForProduct(pr,rg=auditRange()){const prevAudits=(state.store.audits||[]).filter(a=>(a.lines||[]).some(l=>l.productId===pr.id)&&new Date(a.createdAt)<=rg.to).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const prev=prevAudits[0],pl=prev?.lines?.find(l=>l.productId===pr.id);if(!pl)return {prev:null,opening:num(pr?.stock),received:0,available:num(pr?.stock),autoOpening:true};const opening=num(pl.actual);let received=0;const from=new Date(prev.createdAt);for(const r of state.store.stockReceipts||[]){const d=new Date(r.createdAt);if(d<=from||d>rg.to)continue;for(const l of r.lines||[])if(l.productId===pr.id)received+=num(l.quantity)}return {prev,opening,received,available:opening+received,autoOpening:false}}
function currentAuditDraftLines(){return $$('#auditProducts [data-product]').map(r=>{const v=r.querySelector('.actual')?.value;if(v==='')return null;const pr=(state.store.products||[]).find(p=>p.id===r.dataset.product);if(!pr||num(v)===num(pr.stock))return null;const t=auditSimpleForProduct(pr),actual=num(v),available=num(t.available),sold=Math.max(0,available-actual);return {productId:r.dataset.product,before:available,systemBefore:num(pr?.stock),actual,sold,baseline:false,autoBaseline:!!t.autoOpening,reconcileType:'inventory_sales',salePriceSnapshot:num(pr?.salePrice),costPriceSnapshot:effectiveUnitCost(pr||{})}}).filter(Boolean)}
function currentAuditSnapshot(){const lines=currentAuditDraftLines();let soldQty=0,revenue=0,grossCost=0;for(const l of lines){if(l.baseline)continue;const q=Math.max(0,num(l.sold));soldQty+=q;revenue+=q*num(l.salePriceSnapshot);grossCost+=q*num(l.costPriceSnapshot)}return {soldQty,revenue,grossCost,grossProfit:revenue-grossCost,calculatedAt:new Date().toISOString(),mode:'inventory_simple'}}
function renderAuditPeriodSummary(){if(!state.store||!$('#auditSummary'))return;const rg=auditRange(),r=currentAuditSnapshot();$('#auditPeriodLabel').textContent=`Kỳ: ${rg.label}`;$('#auditSummary').innerHTML=`<div class="audit-metric primary-metric"><span>Đã bán</span><strong>${r.soldQty}</strong></div><div class="audit-metric primary-metric"><span>Doanh thu</span><strong>${money(r.revenue)}</strong></div><div class="audit-metric"><span>Giá vốn</span><strong>${money(r.grossCost)}</strong></div><div class="audit-metric primary-metric"><span>Lợi nhuận</span><strong class="${r.grossProfit>=0?'positive':'negative'}">${money(r.grossProfit)}</strong></div>`;$('#auditSummaryNote').textContent=rg.hasPrevious?'Công thức: tồn lần trước + nhập thêm − tồn cuối kỳ = số đã bán.':'Không cần nhập mốc ban đầu: app tự lấy tồn hiện tại trong hệ thống làm mốc và tính ngay khi bạn nhập tồn thực tế.'}
function setupAuditRangeControls(){renderAuditPeriodSummary()}
function auditHistorySummary(a){return a.summarySnapshot||null}
function showAuditDetail(id,edit=false){const a=(state.store.audits||[]).find(x=>x.id===id);if(!a)return;const snap=auditHistorySummary(a)||{},aTime=new Date(a.createdAt);const rows=(a.lines||[]).map(l=>{const pr=(state.store.products||[]).find(p=>p.id===l.productId),sold=l.baseline?0:Math.max(0,num(l.sold??(num(l.before)-num(l.actual)))),hasLater=(state.store.audits||[]).some(x=>x.id!==a.id&&new Date(x.createdAt)>aTime&&(x.lines||[]).some(y=>y.productId===l.productId));return `<div class="audit-detail-row"><div><strong>${esc(l.name||pr?.name||'Mặt hàng')}</strong><small>${l.baseline?'Chốt tồn đầu kỳ':`Có ${l.before} · cuối kỳ ${l.actual} · bán ${sold}`}</small></div>${edit?`<input data-audit-edit-actual="${l.productId}" type="number" min="0" value="${l.actual}" ${hasLater?'disabled title="Không thể đổi tồn vì đã có kỳ kiểm sau"':''}>`:`<strong>${l.baseline?'—':money(sold*num(l.salePriceSnapshot??pr?.salePrice))}</strong>`}</div>`}).join('');modal(`<h3>${edit?'Sửa':'Chi tiết'} kiểm kho</h3><p class="hint">${esc(a.periodLabel||fmtDate(a.createdAt))}</p><div class="audit-metrics compact"><div class="audit-metric"><span>Đã bán</span><strong>${num(snap.soldQty)}</strong></div><div class="audit-metric"><span>Doanh thu</span><strong>${money(snap.revenue||0)}</strong></div><div class="audit-metric"><span>Giá vốn</span><strong>${money(snap.grossCost||0)}</strong></div><div class="audit-metric"><span>Lợi nhuận</span><strong>${money(snap.grossProfit||0)}</strong></div></div><div class="audit-detail-list">${rows}</div>${edit?`<label>Ghi chú<input id="mAuditNote" value="${esc(a.note||'')}"></label><button id="mSaveAuditEdit" class="primary full">Lưu chỉnh sửa</button>`:''}`);if(edit)$('#mSaveAuditEdit').onclick=async()=>{const lines=(a.lines||[]).map(l=>({productId:l.productId,actual:num($(`[data-audit-edit-actual="${l.productId}"]`).value),reconcileType:l.reconcileType||'inventory_sales'}));const edited=(a.lines||[]).map(l=>{const n=lines.find(x=>x.productId===l.productId)||{};const actual=num(n.actual??l.actual),sold=l.baseline?0:Math.max(0,num(l.before)-actual);return {...l,actual,sold}});let soldQty=0,revenue=0,grossCost=0;for(const l of edited){const q=num(l.sold);soldQty+=q;revenue+=q*num(l.salePriceSnapshot);grossCost+=q*num(l.costPriceSnapshot)}const summarySnapshot={soldQty,revenue,grossCost,grossProfit:revenue-grossCost,calculatedAt:new Date().toISOString(),mode:'inventory_simple'};try{await mutate('audit.update',{id:a.id,lines,note:$('#mAuditNote').value,summarySnapshot});closeModal();toast('Đã sửa phiếu kiểm kho')}catch(e){toast(e.message,true)}}}
function renderWarehouse(){renderWarehouseList('audit');renderWarehouseList('stockin');setupAuditRangeControls();$('#stockSupplier').innerHTML='<option value="">Không chọn</option>'+(state.store.suppliers||[]).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');const audits=[...(state.store.audits||[])].reverse().slice(0,20);$('#auditHistory').innerHTML=audits.map(a=>{const snap=auditHistorySummary(a)||{},period=a.periodLabel||fmtDate(a.createdAt);return `<div class="audit-history-card"><div class="audit-history-top"><div><strong>${esc(period)}</strong><div class="audit-history-period">${a.lines?.length||0} mặt hàng</div></div></div><div class="audit-history-money"><span>Đã bán<strong>${num(snap.soldQty)}</strong></span><span>Doanh thu<strong>${money(snap.revenue||0)}</strong></span><span>Giá vốn<strong>${money(snap.grossCost||0)}</strong></span><span>Lợi nhuận<strong>${money(snap.grossProfit||0)}</strong></span></div>${a.note?`<small>${esc(a.note)}</small>`:''}<div class="audit-history-actions"><button class="ghost small" data-view-audit="${a.id}">Xem</button><button class="ghost small" data-edit-audit="${a.id}">Sửa</button><button class="ghost danger small" data-del-audit="${a.id}">Xóa</button></div></div>`}).join('')||'<div class="empty">Chưa có phiếu kiểm kho.</div>';$$('[data-view-audit]').forEach(b=>b.onclick=()=>showAuditDetail(b.dataset.viewAudit));$$('[data-edit-audit]').forEach(b=>b.onclick=()=>showAuditDetail(b.dataset.editAudit,true));$$('[data-del-audit]').forEach(b=>b.onclick=async()=>{const a=(state.store.audits||[]).find(x=>x.id===b.dataset.delAudit),hasLater=(state.store.audits||[]).some(x=>new Date(x.createdAt)>new Date(a?.createdAt));if(!confirm(hasLater?'Phiếu này có kỳ kiểm sau. Xóa có thể ảnh hưởng tồn kho. Vẫn xóa?':'Xóa phiếu kiểm kho?'))return;try{await mutate('audit.delete',{id:b.dataset.delAudit});toast('Đã xóa')}catch(e){toast(e.message,true)}});const rs=[...(state.store.stockReceipts||[])].reverse().slice(0,20);$('#stockinHistory').innerHTML=rs.map(r=>`<div class="list-row"><div><strong>${money(r.totalCost||0)}</strong><small>${fmtDate(r.createdAt)} · ${esc(r.supplier||'')} · ${r.lines?.length||0} mặt hàng</small></div><button class="ghost small" data-edit-r="${r.id}">Sửa</button><button class="ghost danger small" data-del-r="${r.id}">Xóa</button></div>`).join('')||'<div class="empty">Chưa có phiếu nhập.</div>';$$('[data-edit-r]').forEach(b=>b.onclick=()=>showEditStockin(b.dataset.editR));$$('[data-del-r]').forEach(b=>b.onclick=async()=>{if(confirm('Xóa phiếu nhập?'))try{await mutate('stockin.delete',{id:b.dataset.delR});toast('Đã xóa')}catch(e){toast(e.message,true)}})}
$('#auditSearch').oninput=()=>renderWarehouseList('audit');$('#stockinSearch').oninput=()=>renderWarehouseList('stockin');
function changedAuditRows(){return $$('#auditProducts [data-product]').filter(r=>{const input=r.querySelector('.actual');if(!input||input.value==='')return false;const pr=(state.store.products||[]).find(p=>p.id===r.dataset.product);return !!pr&&num(input.value)!==num(pr.stock)})}
function updateAuditDraftDock(){const dock=$('#auditDraftDock');if(!dock||!state.store)return;const rows=changedAuditRows();if(!rows.length){dock.classList.add('hidden');return}let delta=0;for(const r of rows){const pr=(state.store.products||[]).find(p=>p.id===r.dataset.product);delta+=Math.abs(num(r.querySelector('.actual').value)-num(pr?.stock))}$('#auditDraftTitle').textContent=`${rows.length} mặt hàng đã thay đổi`;$('#auditDraftText').textContent=`Chênh ${delta} sản phẩm so với tồn hiện tại`;dock.classList.remove('hidden')}
