function renderMore(){$('#ingredientList').innerHTML=(state.store.ingredients||[]).map(i=>`<div class="list-row"><div><strong>${esc(i.name)}</strong><small>${money(i.purchasePrice)} / ${i.packageQty} ${esc(i.unit)} · tồn ${Math.round(num(i.stock)*100)/100}</small></div><button class="ghost small" data-edit-ing="${i.id}">Sửa</button></div>`).join('')||'<div class="empty">Chưa có nguyên liệu.</div>';$$('[data-edit-ing]').forEach(b=>b.onclick=()=>showIngredientForm(b.dataset.editIng));$('#activityList').innerHTML=[...(state.store.transactions||[])].reverse().slice(0,80).map(t=>`<div class="list-row"><div><strong>${esc(t.summary||t.type)}</strong><small>${fmtDate(t.createdAt)}</small></div></div>`).join('');$('#autoIngredient').checked=!!state.store.config?.ai?.autoIngredientDeduct}
$('#autoIngredient').onchange=async()=>{try{await mutate('config.update',{config:{ai:{autoIngredientDeduct:$('#autoIngredient').checked}}});toast('Đã cập nhật tự trừ nguyên liệu')}catch(e){toast(e.message,true)}};$('#addIngredient').onclick=()=>showIngredientForm('');function showIngredientForm(id){const i=id?state.store.ingredients.find(x=>x.id===id):null;modal(`<h3>${i?'Sửa':'Thêm'} nguyên liệu</h3><div class="form-grid"><label class="wide">Tên<input id="mName" value="${esc(i?.name||'')}"></label><label>Đơn vị<input id="mUnit" value="${esc(i?.unit||'g')}"></label><label>Giá mua<input id="mPrice" value="${i?.purchasePrice||0}"></label><label>Quy cách<input id="mQty" value="${i?.packageQty||1}"></label><label>Tồn<input id="mStock" value="${i?.stock||0}"></label><label class="wide">Ghi chú/công thức<input id="mNote" value="${esc(i?.note||'')}"></label></div><button id="mSave" class="primary full">Lưu</button>`);$('#mSave').onclick=async()=>{try{await mutate(id?'ingredient.update':'ingredient.create',{id,name:$('#mName').value,unit:$('#mUnit').value,purchasePrice:moneyInput($('#mPrice').value),packageQty:num($('#mQty').value),stock:num($('#mStock').value),note:$('#mNote').value});closeModal();toast('Đã lưu nguyên liệu')}catch(e){toast(e.message,true)}}}
$('#askAI').onclick=async()=>{const msg=$('#aiInput').value.trim();if(!msg)return;try{const r=await api('/api/ai/plan',{method:'POST',body:JSON.stringify({storeId:state.storeId,message:msg,context:{}})});if(r.type==='plan'){$('#aiResult').innerHTML=`<p>${esc(r.summary||'AI đã lập kế hoạch')}</p><button id="confirmAI" class="primary">Xác nhận</button>`;$('#confirmAI').onclick=async()=>{try{await mutate('ai.execute',{plan:r.plan,message:msg});toast('Đã thực hiện lệnh AI');$('#aiResult').textContent='Đã thực hiện.'}catch(e){toast(e.message,true)}}}else $('#aiResult').textContent=r.answer||'Không có câu trả lời.'}catch(e){toast(e.message,true)}};
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function downloadJson(x,name){downloadBlob(new Blob([JSON.stringify(x,null,2)],{type:'application/json'}),name)}
$('#exportStore').onclick=()=>downloadJson({format:'cantin-nova-v2',store:state.store},`cantin-nova-${todayKey()}.json`);
function tableHtml(title,rows){if(!rows.length)return `<h2>${title}</h2><table></table>`;const keys=Object.keys(rows[0]).filter(k=>typeof rows[0][k]!=='object');return `<h2>${title}</h2><table border="1"><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(r[k]??'')}</td>`).join('')}</tr>`).join('')}</table>`}
function excelHtml(){const s=state.store;return `<html><head><meta charset="utf-8"></head><body>${tableHtml('Sản phẩm',s.products||[])}${tableHtml('Bán hàng',(s.sales||[]).map(x=>({id:x.id,createdAt:x.createdAt,total:x.total,discount:x.discount||0,costTotal:x.costTotal,profit:x.profit,paymentMethod:x.paymentMethod,customer:x.customer,note:x.note})))}${tableHtml('Công nợ',s.debts||[])}${tableHtml('Thu chi',s.cashEntries||[])}${tableHtml('Nhập hàng',(s.stockReceipts||[]).map(x=>({id:x.id,createdAt:x.createdAt,supplier:x.supplier,totalCost:x.totalCost,paidAmount:x.paidAmount,debtAmount:x.debtAmount,note:x.note})))}${tableHtml('Nhà cung cấp',s.suppliers||[])}${tableHtml('Nợ NCC',s.supplierDebts||[])}</body></html>`}
$('#exportExcel').onclick=()=>downloadBlob(new Blob([excelHtml()],{type:'application/vnd.ms-excel'}),`cantin-nova-${todayKey()}.xls`);
const crcTable=(()=>{let t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();function crc32(u){let c=0xffffffff;for(const b of u)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}function u16(n){return [n&255,(n>>>8)&255]}function u32(n){return [n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]}function zipStored(files){const enc=new TextEncoder(),parts=[],central=[];let off=0;for(const f of files){const name=enc.encode(f.name),data=typeof f.data==='string'?enc.encode(f.data):f.data,crc=crc32(data),local=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...name]);parts.push(local,data);central.push(new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(off),...name]));off+=local.length+data.length}const csize=central.reduce((a,x)=>a+x.length,0),end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(files.length),...u16(files.length),...u32(csize),...u32(off),...u16(0)]);return new Blob([...parts,...central,end],{type:'application/zip'})}
$('#exportZip').onclick=()=>downloadBlob(zipStored([{name:'backup.json',data:JSON.stringify({format:'cantin-nova-v2',store:state.store},null,2)},{name:'report.xls',data:excelHtml()}]),`cantin-nova-${todayKey()}.zip`);
function readStoredZip(buf){const u=new Uint8Array(buf),dv=new DataView(buf),dec=new TextDecoder();let p=0,out={};while(p+30<=u.length&&dv.getUint32(p,true)===0x04034b50){const method=dv.getUint16(p+8,true),size=dv.getUint32(p+18,true),nlen=dv.getUint16(p+26,true),elen=dv.getUint16(p+28,true),name=dec.decode(u.slice(p+30,p+30+nlen)),start=p+30+nlen+elen;if(method!==0)throw new Error('ZIP nén không được hỗ trợ; hãy dùng ZIP do Cantin Nova xuất.');out[name]=u.slice(start,start+size);p=start+size}return out}
$('#importStore').accept='.json,.node.json,.zip,application/json,application/zip';$('#importStore').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{let o;if(f.name.toLowerCase().endsWith('.zip')){const z=readStoredZip(await f.arrayBuffer()),raw=z['backup.json'];if(!raw)throw new Error('ZIP không có backup.json');o=JSON.parse(new TextDecoder().decode(raw))}else o=JSON.parse(await f.text());if(!confirm('Nhập file sẽ thay dữ liệu cửa hàng hiện tại. Tiếp tục?'))return;await mutate('store.import',{store:o.store||o});toast('Đã nhập dữ liệu')}catch(err){toast(err.message,true)}e.target.value=''};
$('#newStore').onclick=()=>{modal('<h3>Tạo cửa hàng mới</h3><label>Tên cửa hàng<input id="mName"></label><button id="mSave" class="primary full">Tạo</button>');$('#mSave').onclick=async()=>{try{await mutate('store.create',{name:$('#mName').value});closeModal();toast('Đã tạo cửa hàng')}catch(e){toast(e.message,true)}}};
function renderAll(){if(!state.store)return;renderHeader();renderDashboard();renderSales();renderDebts();renderWarehouse();renderCashflow();renderCatalog();renderMore();requestAnimationFrame(updateScrollControls)}
boot();
